"""Writes the boot animation's data pack as a C++ header.

    python3 build/embed_xboot_pak.py <xboot.pak> <xboot_pak.h>

The pack comes from theseus/third-party/xboot/tools/pack/pack.py (the
Makefile runs it first). The core reads the pack in place and wants it
aligned to 16 bytes (XB_ALIGN), so the array is declared that way.
"""

import sys


def main():
    src, dst = sys.argv[1], sys.argv[2]
    data = open(src, 'rb').read()
    lines = [
        '// Generated by build/embed_xboot_pak.py from %s. Do not edit.' % src.replace('\\', '/').split('/')[-1],
        '#pragma once',
        '#include <stddef.h>',
        '',
        'alignas(16) static const unsigned char kXbootPak[%d] = {' % len(data),
    ]
    for i in range(0, len(data), 16):
        lines.append('\t' + ', '.join('0x%02x' % b for b in data[i:i + 16]) + ',')
    lines.append('};')
    lines.append('static const size_t kXbootPakSize = sizeof(kXbootPak);')
    lines.append('')
    with open(dst, 'w', newline='\n') as f:
        f.write('\n'.join(lines))


if __name__ == '__main__':
    main()
